sys_ws_operation.operation_script:
(function process(request, response) {

    var timesheetSysId = request.pathParams.daily_timesheet_sys_id;

    if (!timesheetSysId || !/^[0-9a-f]{32}$/i.test(timesheetSysId)) {
        response.setStatus(400);
        response.setBody({
            result: {
                success: false,
                message: "A valid daily_timesheet_sys_id is required"
            }
        });
        return;
    }

    // Verify that the daily timesheet header exists
    var header = new GlideRecordSecure(
        'x_2131768_timesh_0_timesheet_main'
    );

    if (!header.get(timesheetSysId)) {
        response.setStatus(404);
        response.setBody({
            result: {
                success: false,
                message: "Daily timesheet not found"
            }
        });
        return;
    }

    // Retrieve child task entries
    var gr = new GlideRecordSecure(
        'x_2131768_timesh_0_ts_tasks'
    );

    gr.addQuery('timesheet', timesheetSysId);
    gr.query();

    var entries = [];

    while (gr.next()) {
        entries.push({
            entry_sys_id: gr.getUniqueValue(),
            task_sys_id: gr.getValue('tasks'),
            task_name: gr.getDisplayValue('tasks'),
            efforts: gr.getValue('efforts')
        });
    }

    response.setStatus(200);
    response.setBody({
        result: {
            success: true,
            data: {
                time_entries: entries,
                entries_loaded: true
            }
        }
    });

})(request, response);
